import csv
import json
from pathlib import Path
import sys


def read_readings(path):
    groups = {}
    with Path(path).open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames != ["zone", "celsius"]:
            raise ValueError("CSV header must be zone,celsius")
        for row in reader:
            zone = row["zone"].strip()
            if not zone:
                raise ValueError("Each reading needs a zone name")
            groups.setdefault(zone, []).append(float(row["celsius"]))
    if not groups:
        raise ValueError("The input has no readings")
    return groups


def check_reading_counts(groups, minimum):
    for zone, values in groups.items():
        if len(values) < minimum:
            raise ValueError(f"Zone {zone!r} needs at least {minimum} readings")


def write_digest(groups, path, heading):
    lines = [heading]
    for zone in sorted(groups):
        values = groups[zone]
        lines.append(f"{zone}: {sum(values) / len(values):.1f} C")
    Path(path).write_text("\n".join(lines) + "\n", encoding="utf-8")


def main(argv, profile_name="quick", config_path=None):
    if len(argv) != 2:
        print("usage: shift_digest.py INPUT.csv OUTPUT.txt", file=sys.stderr)
        return 2
    if config_path is None:
        config_path = Path(__file__).with_name("profiles.json")
    try:
        profile = json.loads(Path(config_path).read_text(encoding="utf-8"))[profile_name]
        groups = read_readings(argv[0])
        check_reading_counts(groups, profile["minimum_readings_per_zone"])
        write_digest(groups, argv[1], profile["heading"])
    except (OSError, ValueError, KeyError) as error:
        print(str(error), file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))

