#!/usr/bin/env python3
"""Local Harborpack documentation fixture; standard library only."""

import argparse
import json
from pathlib import Path
import re
import sys


class ManifestError(Exception):
    pass


def read_records(path, input_format):
    content = path.read_text(encoding="utf-8")
    if input_format == "json":
        records = json.loads(content)
        if not isinstance(records, list):
            raise ManifestError("json input must be an array")
        return records
    records = []
    for line_number, line in enumerate(content.splitlines(), 1):
        if not line.strip():
            continue
        try:
            records.append(json.loads(line))
        except json.JSONDecodeError as error:
            raise ManifestError(
                "jsonl physical line {}: {}".format(line_number, error.msg)
            ) from error
    return records


def validate(records):
    if not 1 <= len(records) <= 50:
        return ["manifest has {} records; allowed range is 1..50".format(len(records))]
    problems = []
    seen_ids = set()
    for position, record in enumerate(records, 1):
        prefix = "record {}: ".format(position)
        if not isinstance(record, dict):
            problems.append(prefix + "must be an object")
            continue
        unknown = set(record) - {"load_id", "cartons", "note"}
        if unknown:
            problems.append(prefix + "unknown fields: " + ", ".join(sorted(unknown)))
        load_id = record.get("load_id")
        if not isinstance(load_id, str) or re.fullmatch(r"[a-z0-9-]{1,24}", load_id) is None:
            problems.append(prefix + "load_id must match [a-z0-9-]{1,24}")
        elif load_id in seen_ids:
            problems.append(prefix + "duplicate load_id " + load_id)
        else:
            seen_ids.add(load_id)
        cartons = record.get("cartons")
        if type(cartons) is not int or not 1 <= cartons <= 200:
            problems.append(prefix + "cartons must be an integer from 1 through 200")
        if "note" in record:
            note = record["note"]
            if not isinstance(note, str) or len(note) > 120:
                problems.append(prefix + "note must be a string of at most 120 characters")
    return problems


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--input", required=True, type=Path)
    parser.add_argument("--format", required=True, choices=("json", "jsonl"))
    parser.add_argument("--report", choices=("text", "json"), default="text")
    args = parser.parse_args()
    try:
        records = read_records(args.input, args.format)
    except (OSError, UnicodeError, json.JSONDecodeError, ManifestError) as error:
        print("ERROR: " + str(error), file=sys.stderr)
        return 2
    problems = validate(records)
    if problems:
        for problem in problems:
            print("ERROR: " + problem, file=sys.stderr)
        return 2
    summary = {"records": len(records), "cartons": sum(row["cartons"] for row in records)}
    if args.report == "json":
        print(json.dumps(summary, ensure_ascii=False))
    else:
        print("OK: {records} records, {cartons} cartons".format(**summary))
    return 0


if __name__ == "__main__":
    sys.exit(main())
